[
    {"name": "Murr", "coll": "Cats Between Cups", "mood": "Picks his place, asks no permission.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4559479553", "img": "/assets/works/tea/murr/01.webp", "photos": ["/assets/works/tea/murr/01.webp", "/assets/works/tea/murr/02.webp", "/assets/works/tea/murr/03.webp", "/assets/works/tea/murr/04.webp", "/assets/works/tea/murr/05.webp", "/assets/works/tea/murr/06.webp", "/assets/works/tea/murr/07.webp"], "story": "Murr believes every tea table has one perfect place, and somehow it always belongs to him. He does not hurry to make friends and never tries to impress anyone. He watches newcomers carefully and decides for himself who deserves his attention. But once Murr accepts someone, he stays close and treats them like part of his territory. His confidence makes the gathering feel more personal and protected. Murr reminds you that you do not have to belong everywhere. The thing is to find your perfect place in this world.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Familiar · Private · Grounded", "personality": "Selective · Loyal · Self-assured", "profile": []},
    {"name": "Stacklings", "coll": "Cats Between Cups", "mood": "Three troublemakers, one shared plan.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4559486275", "img": "/assets/works/tea/stacklings/01.webp", "photos": ["/assets/works/tea/stacklings/01.webp", "/assets/works/tea/stacklings/02.webp", "/assets/works/tea/stacklings/03.webp", "/assets/works/tea/stacklings/04.webp", "/assets/works/tea/stacklings/05.webp", "/assets/works/tea/stacklings/06.webp"], "story": "Stacklings are three kittens with one shared plan, although none of them knows exactly what the plan is. One climbs, another balances, and the third somehow ends up carrying everyone. They turn small mistakes into games and stories worth remembering. Their energy makes the tea table feel more social, playful, and open to unexpected ideas. They are at their best when everyone joins in and nobody takes the evening too seriously. Stacklings remind you that good company can turn a little chaos into something wonderful.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Playful · Social · Lively", "personality": "Curious · Cooperative · Mischievous", "profile": []},
    {"name": "Purr", "coll": "Cats Between Cups", "mood": "Finds whole worlds in ordinary things.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4559507002", "img": "/assets/works/tea/purr/01.webp", "photos": ["/assets/works/tea/purr/01.webp", "/assets/works/tea/purr/02.webp", "/assets/works/tea/purr/03.webp", "/assets/works/tea/purr/04.webp", "/assets/works/tea/purr/05.webp", "/assets/works/tea/purr/06.webp", "/assets/works/tea/purr/07.webp"], "story": "Purr is always looking at something everyone else has already ignored. A reflection in a cup, a shadow on the wall. One strange thought can hold his attention for a very long time. He follows ideas wherever they lead and often finds connections that nobody expected. Around him, ordinary evenings begin to feel larger, stranger, and full of hidden possibilities. He is the cat for people whose minds keep wandering even when their bodies stay at the table. Purr reminds you that the world becomes more interesting when you keep looking past the obvious.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Reflective · Strange · Expansive", "personality": "Imaginative · Absorbed · Perceptive", "profile": []},
    {"name": "Sionann’s Riverling", "coll": "Waters of the Isles", "mood": "He arrives with questions no one else asks.", "avail": 1, "url": "https://tea-mail.pl/en/collections/ceramika-autorska/products/sionnans-riverling-figurka-herbaciana-ceramika-autorska?variant=58588398780800", "img": "/assets/works/tea/sionanns-riverling/01.webp", "photos": ["/assets/works/tea/sionanns-riverling/01.webp", "/assets/works/tea/sionanns-riverling/02.webp"], "story": "Sionann’s Riverling comes to the tea table with questions no one else thinks to ask. Fresh ideas seem to rise wherever he settles. He turns regular thoughts into stories for everyone, and his curiosity makes every new path feel worth exploring. He never keeps a discovery for himself — Sionann’s Riverling fills each gathering with inspiration and a bright sense of possibility.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Flowing · Curious · Inspired", "personality": "Inquisitive · Generous · Imaginative", "profile": []},
    {"name": "Nessie & the Lochling", "coll": "Waters of the Isles", "mood": "Two wanderers, always side by side.", "avail": 1, "url": "https://tea-mail.pl/en/collections/ceramika-autorska/products/nessie-and-the-lochling-figurka-herbaciana-ceramika-autorska?variant=58597864636800", "img": "/assets/works/tea/nessie-and-the-lochling/01.webp", "photos": ["/assets/works/tea/nessie-and-the-lochling/01.webp"], "story": "Nessie and the Lochling always arrive together. Nessie carries them forward with bold curiosity, while the Lochling watches from above and points out every interesting turn. They bring a sense of shared adventure to the tea table: one follows instinct, the other searches for hidden paths, and their plans often change before the second cup is poured. They make new places feel exciting and familiar places feel fresh. With them nearby, even a small gathering can become a story worth remembering.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Playful · Wandering · Curious", "personality": "Loyal · Adventurous · Mischievous", "profile": []},
    {"name": "Moonshift Selkie", "coll": "Waters of the Isles", "mood": "He lives between two forms.", "avail": 1, "url": "https://tea-mail.pl/en/collections/ceramika-autorska/products/moonshift-selkie-figurka-herbaciana-ceramika-autorska?variant=58597887181184", "img": "/assets/works/tea/moonshift-selkie/01.webp", "photos": ["/assets/works/tea/moonshift-selkie/01.webp"], "story": "Moonshift Selkie lives between two forms, and the moon above his head guides every change. He appears at the tea table during turning points, and his presence makes unfamiliar paths feel possible. He welcomes fresh ideas, uncertain plans, and sudden decisions, carrying the courage of someone who has crossed many thresholds. Around him, people feel ready to leave an old shape behind, and the evening stays open to surprise and transformation. Moonshift Selkie reminds you that becoming someone new can bring you closer to yourself.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Moonlit · Tidal · Transformative", "personality": "Elusive · Instinctive · Brave", "profile": []},
    {"name": "Selki", "coll": "Waters of the Isles", "mood": "The ocean’s playful wanderer.", "avail": 1, "url": "https://tea-mail.pl/en/collections/ceramika-autorska/products/selki-figurka-herbaciana-ceramika-autorska?variant=58597814403456", "img": "/assets/works/tea/selki/01.webp", "photos": ["/assets/works/tea/selki/01.webp", "/assets/works/tea/selki/02.webp", "/assets/works/tea/selki/03.webp"], "story": "Selki carries the playful spirit of the ocean and the joy of coastal waters. He brings the feeling of a sea creature that loves to explore new waves and hidden places, and his energy fills the tea gathering with curiosity, movement, and a sense of adventure. Sitting with him inspires open thoughts and fresh ideas that flow naturally, turning every tea moment into a small voyage filled with imagination and discovery. Selki is the cheerful companion who brings the ocean closer to the table.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Playful · Flowing · Adventurous", "personality": "Curious · Lively · Free-spirited", "profile": []},
    {"name": "Kelpi", "coll": "Waters of the Isles", "mood": "Guardian of wonder and the deep.", "avail": 1, "url": "https://tea-mail.pl/en/collections/ceramika-autorska/products/kelpi-figurka-herbaciana-ceramika-autorska?variant=58597852152192", "img": "/assets/works/tea/kelpi/01.webp", "photos": ["/assets/works/tea/kelpi/01.webp"], "story": "Kelpi carries the wild spirit of the deep water and the mystery of hidden shores. He watches over the tea space like an ancient river creature that knows forgotten stories, and his presence brings a sense of discovery that invites you to follow your curiosity. Sitting with him opens the door to imagination, strange ideas, and unexpected connections. He reminds everyone that every tea gathering can become a small journey into the unknown. Kelpi is the guardian of wonder and exploration.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Mysterious · Curious · Dreamlike", "personality": "Wild · Observant · Enigmatic", "profile": []},
    {"name": "Bari", "coll": "Tea Ceremony", "mood": "He hears the tea change its voice.", "avail": 0, "url": "", "img": "/assets/works/tea/bari/01.webp", "photos": ["/assets/works/tea/bari/01.webp", "/assets/works/tea/bari/02.webp", "/assets/works/tea/bari/03.webp", "/assets/works/tea/bari/04.webp", "/assets/works/tea/bari/05.webp", "/assets/works/tea/bari/06.webp"], "story": "Bari loves how the tea changes its voice from the first pour to the last. He pays close attention to the way a lively start melts into a deep, comforting warmth, and how your own thoughts shift right along with the flavor. He also has a soft spot for beautiful teaware, knowing that the right clay cup adds a special touch to the drink. Sitting with him turns a regular tea break into a small, perfect moment of joy.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Warm · Curious · Present", "personality": "Observant · Focused · Welcoming", "profile": []},
    {"name": "Crumble", "coll": "Tea Ceremony", "mood": "He finds the bite that lifts the brew.", "avail": 0, "url": "", "img": "/assets/works/tea/crumble/01.webp", "photos": ["/assets/works/tea/crumble/01.webp", "/assets/works/tea/crumble/02.webp", "/assets/works/tea/crumble/03.webp", "/assets/works/tea/crumble/04.webp", "/assets/works/tea/crumble/05.webp", "/assets/works/tea/crumble/06.webp"], "story": "Crumble believes a good tea session is never truly complete without a thoughtful snack. He approaches sweet pairings like a tiny, focused chef, always hunting for the precise piece of dried fruit or biscuit that highlights a brew's notes. He understands that a snack must never dominate; it exists solely to make the tea taste even better. Sitting with him transforms every tea break into a small, playful tasting adventure, sparking ideas for perfect combinations. He is the ultimate soulmate for those who know that the best moments are found at the intersection of a perfect pour and a well-chosen bite.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Flavorful · Cozy · Attentive", "personality": "Joyful · Discerning · Playful", "profile": []},
    {"name": "Natter", "coll": "Tea Ceremony", "mood": "He brews best with good conversation.", "avail": 0, "url": "", "img": "/assets/works/tea/natter/01.webp", "photos": ["/assets/works/tea/natter/01.webp", "/assets/works/tea/natter/02.webp", "/assets/works/tea/natter/03.webp", "/assets/works/tea/natter/04.webp"], "story": "Natter thrives on shared moments and good talk. He adores the sound of voices gathering around a teapot and finds that tea tastes best when mixed with laughter and interesting stories. Sitting with him makes your own words flow more freely and the room feel warmer. Natter is a soulmate for the social and the chatty, for anyone who finds their deepest joy in shared conversation.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Lively · Connected · Social", "personality": "Playful · Chatty · Engaging", "profile": []},
    {"name": "Sen", "coll": "Tea Ceremony", "mood": "An explorer of rare leaves and blends.", "avail": 0, "url": "", "img": "/assets/works/tea/sen/01.webp", "photos": ["/assets/works/tea/sen/01.webp", "/assets/works/tea/sen/02.webp", "/assets/works/tea/sen/03.webp", "/assets/works/tea/sen/04.webp", "/assets/works/tea/sen/05.webp"], "story": "Sen is a true explorer of the tea world. He spends his days discovering rare harvests and fascinating fresh blends. He understands the secret language of the leaves, knowing exactly how a specific twist or color will bloom in the hot water. Sitting with him turns a regular tasting into an exciting journey of flavors and aromas. He is a wonderful companion for anyone who loves to learn about their drink and dive deep into the rich story of every single leaf.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Inquisitive · Earthy · Engaging", "personality": "Knowledgeable · Adventurous · Focused", "profile": []},
    {"name": "Shin", "coll": "Tea Ceremony", "mood": "A purist devoted to one perfect tea.", "avail": 0, "url": "", "img": "/assets/works/tea/shin/01.webp", "photos": ["/assets/works/tea/shin/01.webp", "/assets/works/tea/shin/02.webp", "/assets/works/tea/shin/03.webp", "/assets/works/tea/shin/04.webp"], "story": "Shin is a devoted purist, holding a single, cherished tea close to his heart. He has dedicated endless hours to mastering this one flavor, exploring every possible way to brew it perfectly. His true skill lies in the art of the pour; he surprises you by showing how different waters, temperatures, and timing can make the same leaves taste entirely new. One minute his brew is vibrant and fresh, the next it is deep and resonant. Shin is a wonderful companion for those who appreciate depth, dedication, and the beautiful magic that happens when you truly focus on just one thing.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Dedicated · Essential · Depth", "personality": "Devout · Precise · Expert", "profile": []},
    {"name": "Tetsu", "coll": "Tea Ceremony", "mood": "The steady heart of the tea gathering.", "avail": 0, "url": "", "img": "/assets/works/tea/tetsu/01.webp", "photos": ["/assets/works/tea/tetsu/01.webp", "/assets/works/tea/tetsu/02.webp", "/assets/works/tea/tetsu/03.webp", "/assets/works/tea/tetsu/04.webp", "/assets/works/tea/tetsu/05.webp"], "story": "Tetsu holds the silent, centered core of the tea gathering. He orchestrates the movement of hot water and the unfurling of leaves with effortless assurance. He understands the unseen rhythms that draw people closer around the pot. Sitting with him grounds your energy and brings a deliberate, focused clarity to the moment. He guides the entire flow of the evening, ensuring a shared, intentional experience for everyone present. Tetsu is the steady, reassuring heart of the session.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Focused · Shared · Grounded", "personality": "Assured · Discerning · Centered", "profile": []},
    {"name": "Faelan", "coll": "Wildbloom", "mood": "His heart overflows with beauty.", "avail": 0, "url": "", "img": "/assets/works/tea/faelan/01.webp", "photos": ["/assets/works/tea/faelan/01.webp", "/assets/works/tea/faelan/02.webp", "/assets/works/tea/faelan/03.webp", "/assets/works/tea/faelan/04.webp", "/assets/works/tea/faelan/05.webp"], "story": "Faelan carries a heart so full it cannot stay hidden. Everything he feels rises up and spills out into the world as something lovely. He gives that beauty away freely and asks for nothing in return. Faelan is a soulmate for the warm-hearted and the generous, for anyone who loves to leave the world around them a little softer and brighter.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Tender · Flourishing · Open-Hearted", "personality": "Generous · Warm · Giving", "profile": []},
    {"name": "Liriel", "coll": "Wildbloom", "mood": "Flowers bloom wherever he rests.", "avail": 0, "url": "", "img": "/assets/works/tea/liriel/01.webp", "photos": ["/assets/works/tea/liriel/01.webp", "/assets/works/tea/liriel/02.webp", "/assets/works/tea/liriel/03.webp", "/assets/works/tea/liriel/04.webp", "/assets/works/tea/liriel/05.webp"], "story": "Liriel brings life with him everywhere he goes. Wherever he settles, flowers wake up and begin to bloom across him. He cannot help it, growth follows him the way light follows the morning. He loves to watch small things open up and reach toward the sky. Liriel is a soulmate for creators, makers, and dreamers, for anyone who feels most alive when they are helping something grow.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Blooming · Lively · Abundant", "personality": "Nurturing · Joyful · Life-Bringing", "profile": []},
    {"name": "Fenn", "coll": "Wildbloom", "mood": "Keeps the patience of green places.", "avail": 0, "url": "", "img": "/assets/works/tea/fenn/01.webp", "photos": ["/assets/works/tea/fenn/01.webp", "/assets/works/tea/fenn/02.webp", "/assets/works/tea/fenn/03.webp", "/assets/works/tea/fenn/04.webp", "/assets/works/tea/fenn/05.webp", "/assets/works/tea/fenn/06.webp", "/assets/works/tea/fenn/07.webp"], "story": "Fenn lives at the pace of moss and fern. He has learned that good things take their time, and there is no need to hurry any of it. Sitting with him makes your breathing grow deeper and your shoulders come down. He finds contentment in damp mornings, green corners, and long, unbothered hours. Fenn is a soulmate for the patient and the grounded, for anyone who wants to step out of the rush and feel held by something steady.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Restful · Green · Grounded", "personality": "Patient · Steady · Peaceful", "profile": []},
    {"name": "Pell", "coll": "Wildbloom", "mood": "Hides beneath a single leaf.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4539531982", "img": "/assets/works/tea/pell/01.webp", "photos": ["/assets/works/tea/pell/01.webp", "/assets/works/tea/pell/02.webp", "/assets/works/tea/pell/03.webp", "/assets/works/tea/pell/04.webp", "/assets/works/tea/pell/05.webp", "/assets/works/tea/pell/06.webp"], "story": "Pell likes to keep to himself, tucked away under one big leaf where the world cannot reach him. Crowds and noise wear him out, and he gathers his strength back in his own shade. Under his leaf he feels safe enough to be fully himself. He will share his little hideaway with the few people he truly trusts. Pell is a soulmate for introverts and homebodies, for anyone who needs a small, sheltered place to retreat and feel like themselves again.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Sheltered · Quiet · Cozy", "personality": "Shy · Gentle · Self-Contained", "profile": []},
    {"name": "Senna", "coll": "Wildbloom", "mood": "Gives shape to drifting ideas.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4539517289", "img": "/assets/works/tea/senna/01.webp", "photos": ["/assets/works/tea/senna/01.webp", "/assets/works/tea/senna/02.webp", "/assets/works/tea/senna/03.webp", "/assets/works/tea/senna/04.webp", "/assets/works/tea/senna/05.webp", "/assets/works/tea/senna/06.webp", "/assets/works/tea/senna/07.webp", "/assets/works/tea/senna/08.webp"], "story": "Senna spends his days half-asleep, catching the ideas that drift unseen through the air. Most of them arrive faint and unfinished, barely more than a feeling. He holds each one close as he dreams and helps it grow into something whole and beautiful. Senna is a soulmate for thinkers, writers, and creators, for anyone with a head full of half-formed ideas waiting to become real.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Dreaming · Imaginative · Drifting", "personality": "Imaginative · Dreamy · Quietly Inventive", "profile": []},
    {"name": "Eylin", "coll": "Nightsong", "mood": "Keeps watch over the sleeping world.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4536719581", "img": "/assets/works/tea/eylin/01.webp", "photos": ["/assets/works/tea/eylin/01.webp", "/assets/works/tea/eylin/02.webp", "/assets/works/tea/eylin/03.webp", "/assets/works/tea/eylin/04.webp", "/assets/works/tea/eylin/05.webp", "/assets/works/tea/eylin/06.webp", "/assets/works/tea/eylin/07.webp"], "story": "Eylin never sleeps when night comes. He stays awake and listens to the world growing around him. He loves to watch over everyone while they rest, the whole world breathing softly and safe. In those long hours his mind drifts into warm, wandering daydreams. Eylin is a soulmate for anyone who feels most at home late at night, when the world finally settles and the only company you need is your own thoughts.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Nocturnal · Watchful · Dreaming", "personality": "Wakeful · Tender · Observant", "profile": []},
    {"name": "Virel", "coll": "Nightsong", "mood": "Wanders between the stars.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4536738626", "img": "/assets/works/tea/virel/01.webp", "photos": ["/assets/works/tea/virel/01.webp", "/assets/works/tea/virel/02.webp", "/assets/works/tea/virel/03.webp", "/assets/works/tea/virel/04.webp", "/assets/works/tea/virel/05.webp", "/assets/works/tea/virel/06.webp", "/assets/works/tea/virel/07.webp", "/assets/works/tea/virel/08.webp", "/assets/works/tea/virel/09.webp"], "story": "Virel spends every night travelling between the stars. He drifts from one distant light to the next and never stays in one place for long. He gathers the wonders he finds out there and brings a little of them back to your table. When you sit with him, he invites your mind to leave the room and roam somewhere far away. Virel is a soulmate for restless dreamers and wanderers, for anyone whose thoughts feel too big for the ceiling above their bed.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Starbound · Wandering · Boundless", "personality": "Curious · Free-Spirited · Far-Roaming", "profile": []},
    {"name": "Lyr", "coll": "Nightsong", "mood": "Sings the night's songs with the wind.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4536741852", "img": "/assets/works/tea/lyr/01.webp", "photos": ["/assets/works/tea/lyr/01.webp", "/assets/works/tea/lyr/02.webp", "/assets/works/tea/lyr/03.webp", "/assets/works/tea/lyr/04.webp", "/assets/works/tea/lyr/05.webp", "/assets/works/tea/lyr/06.webp"], "story": "Lyr sings through the night together with the wind. The two of them trade songs about everything that happened during the day. They sing about the small joys, the things that went wrong, and the worries you carry to bed. By the time the song fades, those worries feel lighter and easier to set down. Lyr is a soulmate for anyone who needs to let the day go before they can rest, and who finds comfort in a gentle voice in the dark.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Melodic · Windswept · Soothing", "personality": "Expressive · Gentle · Reassuring", "profile": []},
    {"name": "Sylin", "coll": "Nightsong", "mood": "Dances with the night moths.", "avail": 0, "url": "https://darksagaart.etsy.com/listing/4536744970", "img": "/assets/works/tea/sylin/01.webp", "photos": ["/assets/works/tea/sylin/01.webp", "/assets/works/tea/sylin/02.webp", "/assets/works/tea/sylin/03.webp", "/assets/works/tea/sylin/04.webp", "/assets/works/tea/sylin/05.webp", "/assets/works/tea/sylin/06.webp"], "story": "Sylin spends the night dancing in a ring of moths. They turn and drift around him in a soft, weightless circle. If your day was heavy, he pulls you into the dance until your shoulders feel light again. When you lose your way in the dark, he helps you find the nearest light and follow it home. Sylin is a soulmate for anyone worn out by a long day, who needs to feel light and a little bit found again.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Dancing · Weightless · Lighthearted", "personality": "Playful · Uplifting · Guiding", "profile": []},
    {"name": "Wynn", "coll": "Nightsong", "mood": "Refuses to miss the night.", "avail": 1, "url": "https://darksagaart.etsy.com/listing/4536730697", "img": "/assets/works/tea/wynn/01.webp", "photos": ["/assets/works/tea/wynn/01.webp", "/assets/works/tea/wynn/02.webp", "/assets/works/tea/wynn/03.webp", "/assets/works/tea/wynn/04.webp", "/assets/works/tea/wynn/05.webp", "/assets/works/tea/wynn/06.webp"], "story": "Wynn is worn out, and still he refuses to go to bed. Every night he plants himself on his feet and fights to keep his heavy eyes open a little longer. The dark hours feel too quiet and too precious for him to sleep through them. He would sooner sway where he stands, half-dreaming, than miss a single moment of the stillness he loves. Wynn is a soulmate for everyone who stays up far too late, who knows they should rest but cannot let go of the stillness of a late, quiet night.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Nocturnal · Hushed · Heavy-Eyed", "personality": "Stubborn · Drowsy · Wistful", "profile": []},
    {"name": "Aven", "coll": "Nightsong", "mood": "Comes alive when the sun goes down.", "avail": 0, "url": "", "img": "/assets/works/tea/aven/01.webp", "photos": ["/assets/works/tea/aven/01.webp", "/assets/works/tea/aven/02.webp", "/assets/works/tea/aven/03.webp", "/assets/works/tea/aven/04.webp", "/assets/works/tea/aven/05.webp"], "story": "Aven comes alive the moment the sun goes down. All day he saves his energy, and once night falls he is finally ready to go, with his playful little companion bouncing and tumbling on his back. The two of them treat the dark hours as their own private playground, with all the room in the world to move and create. While everyone else is winding down, Aven is only getting started. Aven is a soulmate for night people and late bloomers, for everyone who does their best living, thinking, and creating long after midnight.", "series": "Tea Spirits", "vibe": "", "atmosphere": "Nocturnal · Playful · Energized", "personality": "Spirited · Playful · Easygoing", "profile": []},
    {name:"Eloran",coll:"Echo Catchers",mood:"An iron vault built for heavy regrets",avail:0,url:"https://darksagaart.etsy.com/listing/4527877608/",img:"/assets/works/tea/eloran/01.webp",photos:["/assets/works/tea/eloran/01.webp", "/assets/works/tea/eloran/02.webp", "/assets/works/tea/eloran/03.webp", "/assets/works/tea/eloran/04.webp", "/assets/works/tea/eloran/05.webp", "/assets/works/tea/eloran/06.webp"],story:"Eloran is built for the secrets you no longer want to carry, the echoes you wish you could completely erase. He acts as a black hole for heavy thoughts. Once you speak a regret or a sharp memory into his presence, he locks it away so deep that it can never resurface to hurt you again. Eloran is a soulmate for anyone who needs to bury a piece of their past, drop their armor, and finally feel light again.",series:"Tea Spirits",vibe:"",atmosphere:"Heavy · Sealed · Forgiving",personality:"Unyielding · Protective · Stern",profile:[]},
    {name:"Kaelen",coll:"Echo Catchers",mood:"Holds the tangible shape of your secret",avail:0,url:"https://darksagaart.etsy.com/listing/4527753628/",img:"/assets/works/tea/kaelen/01.webp",photos:["/assets/works/tea/kaelen/01.webp", "/assets/works/tea/kaelen/02.webp", "/assets/works/tea/kaelen/03.webp", "/assets/works/tea/kaelen/04.webp", "/assets/works/tea/kaelen/05.webp", "/assets/works/tea/kaelen/06.webp"],story:"Kaelen is the one who caught the very first vibration in the room. Within his dark, heavy form, he turned that fleeting whisper into something permanent. The small, bright bloom he holds is the tangible shape of a secret that will never be lost or repeated. He is a steadfast companion for anyone who needs to let a thought go, knowing it has finally found a safe place to rest.",series:"Tea Spirits",vibe:"",atmosphere:"Intimate · Mystical · Sheltered",personality:"Attentive · Guarded · Devoted",profile:[]},
    {name:"Morwen",coll:"Echo Catchers",mood:"He guides hidden wisdom into the light",avail:0,url:"https://darksagaart.etsy.com/listing/4529682099/reserved-bundle-of-4-tea-pets?show_sold_out_detail=1&ref=nla_listing_details",img:"/assets/works/tea/morwen/01.webp",photos:["/assets/works/tea/morwen/01.webp", "/assets/works/tea/morwen/02.webp", "/assets/works/tea/morwen/03.webp", "/assets/works/tea/morwen/04.webp", "/assets/works/tea/morwen/05.webp", "/assets/works/tea/morwen/06.webp"],story:"Morwen is here to help your truest, most important internal secrets finally break through the dark. He is tuned to the deepest layers of your subconscious, hidden talents, and sudden realizations you keep locked away because you're afraid to face them. Morwen is a soulmate for those standing at a crossroads, helping you unearth your own hidden wisdom and gently guiding it out into the light during a tea session.",series:"Tea Spirits",vibe:"",atmosphere:"Illuminating · Ancient · Awakening",personality:"Guiding · Nurturing · Wise",profile:[]},
    {name:"Soren",coll:"Echo Catchers",mood:"Guards your fragile daydreams in the dark",avail:0,url:"https://darksagaart.etsy.com/listing/4527898965/",img:"/assets/works/tea/soren/01.webp",photos:["/assets/works/tea/soren/01.webp", "/assets/works/tea/soren/02.webp", "/assets/works/tea/soren/03.webp", "/assets/works/tea/soren/04.webp", "/assets/works/tea/soren/05.webp", "/assets/works/tea/soren/06.webp", "/assets/works/tea/soren/07.webp"],story:"Soren is drawn to the softest, most fragile echoes: the daydreams, the memories of your childhood and home, and the secret wishes you whisper to the ceiling right before you fall asleep. Soren catches those delicate, half-asleep thoughts and keeps them safe from the harsh light of daytime logic. He is a soulmate for overthinkers and quiet dreamers, ensuring that your wildest, most vulnerable ambitions can safely breathe in the dark until you are ready to make them real.",series:"Tea Spirits",vibe:"",atmosphere:"Serene · Dreamlike · Restorative",personality:"Gentle · Protective · Vigilant",profile:[]},
    {name:"Vaelis",coll:"Echo Catchers",mood:"A safe harbor protecting from outside noise",avail:0,url:"https://darksagaart.etsy.com/listing/4529682099/reserved-bundle-of-4-tea-pets?show_sold_out_detail=1&ref=nla_listing_details",img:"/assets/works/tea/vaelis/01.webp",photos:["/assets/works/tea/vaelis/01.webp", "/assets/works/tea/vaelis/02.webp", "/assets/works/tea/vaelis/03.webp", "/assets/works/tea/vaelis/04.webp", "/assets/works/tea/vaelis/05.webp", "/assets/works/tea/vaelis/06.webp", "/assets/works/tea/vaelis/07.webp"],story:"Vaelis knows exactly how overwhelming the big, loud world can feel. He chose this heavy stone as his sanctuary, a tiny spot where the chaos cannot reach him. He is a collector of vulnerable thoughts, the fragile, half-whispered secrets you only dare to say out loud when everything else fades away. Vaelis catches those delicate echoes and hides them safely under his massive rock, protecting them (and you) from the outside noise. He is the perfect soulmate for anyone who sometimes needs to shrink their world down, take a deep breath, and feel completely protected.",series:"Tea Spirits",vibe:"",atmosphere:"Sheltered · Cozy · Mystical",personality:"Vulnerable · Protective · Tender",profile:[]},
    {name:"Vrix",coll:"Echo Catchers",mood:"He looks at your mystery upside down",avail:0,url:"https://darksagaart.etsy.com/listing/4529682099/reserved-bundle-of-4-tea-pets?show_sold_out_detail=1&ref=nla_listing_details",img:"/assets/works/tea/vrix/01.webp",photos:["/assets/works/tea/vrix/01.webp", "/assets/works/tea/vrix/02.webp", "/assets/works/tea/vrix/03.webp", "/assets/works/tea/vrix/04.webp", "/assets/works/tea/vrix/05.webp", "/assets/works/tea/vrix/06.webp"],story:"Vrix refuses to look at the world the way everyone else does. And he also challenges you to change your view. He is the catcher of your most unconventional echoes and the strange ideas, the sudden flashes of genius, and the thoughts that only make sense when you turn your problems upside down. Vrix is the perfect soulmate for those who are tired of overthinking their burdens and need a companion who can find the unexpected truth hidden behind any mystery.",series:"Tea Spirits",vibe:"",atmosphere:"Abstract · Avant-Garde · Revealing",personality:"Eccentric · Insightful · Shifting",profile:[]},
    {name:"Zael",coll:"Echo Catchers",mood:"The keeper of your wildest internal sparks",avail:0,url:"https://darksagaart.etsy.com/listing/4529682099/reserved-bundle-of-4-tea-pets?show_sold_out_detail=1&ref=nla_listing_details",img:"/assets/works/tea/zael/01.webp",photos:["/assets/works/tea/zael/01.webp", "/assets/works/tea/zael/02.webp", "/assets/works/tea/zael/03.webp", "/assets/works/tea/zael/04.webp", "/assets/works/tea/zael/05.webp", "/assets/works/tea/zael/06.webp", "/assets/works/tea/zael/07.webp"],story:"Zael is here for your wild ideas, late-night conspiracies, and the secrets that make you laugh when you shouldn't. He catches the echo of your boldest dreams and unspent adrenaline. He is the keeper of your inner spark, the one who reminds you that rules are meant to be questioned and that life is too fast to stay serious. Zael is the ultimate soulmate for those who hide a rebellious streak beneath a calm exterior and need a loyal partner in crime on their desk.",series:"Tea Spirits",vibe:"",atmosphere:"Bold · Mischievous · Dynamic",personality:"Audacious · Curious · Playful",profile:[]},
    {name:"Sumi",mood:"The ink-pine sentinel.",avail:0,url:"",img:"/assets/works/tea/sumi/01.webp",photos:["/assets/works/tea/sumi/01.webp", "/assets/works/tea/sumi/02.webp", "/assets/works/tea/sumi/03.webp", "/assets/works/tea/sumi/04.webp"],story:"Meet Sumi, the Ink-Pine Sentinel. Sumi is a calm pine spirit with the patience of old trees and the clarity of a single brushstroke. He brings a sense of stillness to the tea table, the kind that makes a space feel more grounded, focused, and serene. One of Sumi's horns remained smaller, like an unfinished line in an ink painting; rather than taking away from him, this asymmetry gives him individuality and deepens his wabi-sabi presence. With pine motifs across his body and a pale mask-like face, Sumi feels like a small guardian of misty groves, stone paths, and unhurried rituals. Keep him near during tea as a reminder to pause, breathe, and appreciate the beauty of forms that are a little irregular, a little weathered, and entirely their own.",series:"Tea Spirits",vibe:"",atmosphere:"Meditative · Minimalist · Wabi-Sabi",personality:"Calm · Attentive · Reserved · Grounded",profile:[]},
    {name:"Marl",mood:"The beauty collector.",avail:1,url:"https://darksagaart.etsy.com/listing/4496790129/",img:"/assets/works/tea/marl/01.webp",photos:["/assets/works/tea/marl/01.webp", "/assets/works/tea/marl/02.webp", "/assets/works/tea/marl/03.webp", "/assets/works/tea/marl/04.webp", "/assets/works/tea/marl/05.webp", "/assets/works/tea/marl/06.webp"],story:"Marl, the Beauty Collector. Marl is a flower slug with a patient eye for beauty. He slowly gathers the delicate things most creatures pass by: fallen petals, pale blossoms, soft shadows, tiny marks in stone, and the gentle shapes left by time. Do you love to collect small beautiful things, enjoy botanical details, like your tea rituals to feel personal, poetic, and a little unusual?",series:"Tea Spirits",vibe:"",atmosphere:"Botanical · Poetic · Earthy",personality:"Observant · Tender · Devoted to Beauty",profile:[]},
    {name:"Kovu",mood:"Spirit of constant flow.",avail:0,url:"https://darksagaart.etsy.com/listing/4461262134/",img:"/assets/works/tea/kovu/01.webp",photos:["/assets/works/tea/kovu/01.webp", "/assets/works/tea/kovu/02.webp", "/assets/works/tea/kovu/03.webp", "/assets/works/tea/kovu/04.webp"],story:"Kovu, the Spirit of Constant Flow. Kovu is not a spirit of stillness, but of transition. He represents the moment of change,like a sprout breaking through the soil or a river turning a corner. His body is captured in a fluid, reclining curve, showing that true strength lies in flexibility and the ability to adapt to the ever-changing world. Kovu is a powerful companion for your tea ceremony if you seek inspiration, growth, or a reminder that life is a beautiful, never-ending movement.",series:"Tea Spirits",vibe:"",atmosphere:"Transformative · Fluid · Energetic",personality:"Adaptable · Flexible · Resilient",profile:[]},
    {name:"Mura",mood:"Spirit of the night forest.",avail:0,url:"https://darksagaart.etsy.com/listing/4461263485/",img:"/assets/works/tea/mura/01.webp",photos:["/assets/works/tea/mura/01.webp", "/assets/works/tea/mura/02.webp", "/assets/works/tea/mura/03.webp", "/assets/works/tea/mura/04.webp", "/assets/works/tea/mura/05.webp"],story:"Mura, the Spirit of the Night Forest. Mura is a silent guardian who appears when the moon is high. On his head, he carries a small crescent moon, a symbol of light that guides him through the darkness. His body is covered with hand-carved patterns of ancient, leafless branches, making him look like a part of an old winter tree. Mura doesn't need leaves to be beautiful; he represents the deep strength of roots and the quiet peace of the cold woods. He is a perfect companion for late-night tea sessions or quiet moments of meditation. He brings a calm, grounded energy to your tea tray.",series:"Tea Spirits",vibe:"",atmosphere:"Midnight · Winter Forest · Calm",personality:"Wise · Silent · Strong",profile:[]},
    {name:"Solas",mood:"Voice of the embers.",avail:0,url:"https://darksagaart.etsy.com/listing/4452444013/",img:"/assets/works/tea/solas/01.webp",photos:["/assets/works/tea/solas/01.webp", "/assets/works/tea/solas/02.webp", "/assets/works/tea/solas/03.webp", "/assets/works/tea/solas/04.webp", "/assets/works/tea/solas/05.webp"],story:"Solas, the Voice of the Embers. Part of a small circle of spirits who gather around the sacred forest fire, Solas is the one who keeps the ancient melodies alive. He sings songs that only the trees and the rising steam can truly understand. Hand-sculpted from dark, textured clay, Solas features flowing spiral engravings on his sides,symbols of sound waves and the eternal rhythm of nature. A bright mystical rune is etched on his back, acting as a tuning fork for the energy of your tea space. He is the perfect companion for those who find music in the ritual of brewing. Whether you are listening to the whistle of the kettle or the quiet pour of water, Solas stands as a reminder to find your own voice and melody in the everyday.",series:"Tea Spirits",vibe:"",atmosphere:"Melodic · Uplifting · Vibrant",personality:"Expressive · Joyful · Soulful",profile:[]},
    {name:"Pio",mood:"Heart of the forest choir.",avail:0,url:"https://darksagaart.etsy.com/listing/4461268972/",img:"/assets/works/tea/pio/01.webp",photos:["/assets/works/tea/pio/01.webp", "/assets/works/tea/pio/02.webp", "/assets/works/tea/pio/03.webp", "/assets/works/tea/pio/04.webp"],story:"Pio, the Heart of the Forest Choir. The final member of the campfire circle, Pio is the embodiment of kindness and universal harmony. While others sing or dream, Pio simply is. His energy is so warm and welcoming that the forest birds treat him as their favorite resting place, perching on his shoulders and even nesting on his head. He brings a sense of gentle companionship to your tea ceremony, reminding us that when we are at peace, the whole world wants to be near us.",series:"Tea Spirits",vibe:"",atmosphere:"Harmonious · Kind · Grateful",personality:"Gentle · Welcoming · Serene",profile:[]},
    {name:"Kitsune",mood:"Mischievous nine-tailed fox.",avail:0,url:"https://darksagaart.etsy.com/listing/4428429968/",img:"/assets/works/tea/kitsune/01.webp",photos:["/assets/works/tea/kitsune/01.webp", "/assets/works/tea/kitsune/02.webp", "/assets/works/tea/kitsune/03.webp", "/assets/works/tea/kitsune/04.webp", "/assets/works/tea/kitsune/05.webp"],story:"Kitsune, a mischievous nine-tailed kitsune tea pet who arrives with an unexpected companion: a tiny chicken perched on her head, as if it's the most natural crown in the world. She adores good tea (the kind that lingers on the tongue) and lives for interesting conversations, secrets, stories, bold opinions, laughter that warms the cups.",series:"Tea Spirits",vibe:"",atmosphere:"",personality:"",profile:[]},
    {name:"Pip",mood:"The silent perch.",avail:0,url:"https://darksagaart.etsy.com/listing/4428443395/",img:"/assets/works/tea/pip/01.webp",photos:["/assets/works/tea/pip/01.webp", "/assets/works/tea/pip/02.webp", "/assets/works/tea/pip/03.webp", "/assets/works/tea/pip/04.webp", "/assets/works/tea/pip/05.webp"],story:"Pip, the Silent Perch. Pip is a spirit of such immense stillness and kindness that even the shiest forest birds feel safe enough to rest on him.",series:"Tea Spirits",vibe:"",atmosphere:"Serene · Gentle · Harmonious",personality:"Kind-hearted · Patient · Welcoming",profile:[]},
    {name:"Nox",mood:"The star-sleeper.",avail:0,url:"https://darksagaart.etsy.com/listing/4428435911/",img:"/assets/works/tea/nox/01.webp",photos:["/assets/works/tea/nox/01.webp", "/assets/works/tea/nox/02.webp", "/assets/works/tea/nox/03.webp"],story:"Nox, the Star-Sleeper. While the other spirits guard the forest, Nox is the keeper of its dreams. He only wakes when the moon is high, but for your tea ceremony he offers a quiet, grounding presence. He does not demand attention; he simply shares his calm with you.",series:"Tea Spirits",vibe:"",atmosphere:"Dreamy · Night-time · Peaceful",personality:"Quiet · Gentle · Restful",profile:[]},
    {name:"Runehorn Sentinel",mood:"Quiet horned guardian.",avail:0,url:"https://darksagaart.etsy.com/listing/4428425896/",img:"/assets/works/tea/runehorn-sentinel/01.webp",photos:["/assets/works/tea/runehorn-sentinel/01.webp", "/assets/works/tea/runehorn-sentinel/02.webp", "/assets/works/tea/runehorn-sentinel/03.webp"],story:"Somewhere between smoke, tea steam, and old forest silence, the Runehorn Sentinel keeps watch. This handmade unglazed ceramic tea pet is a small horned guardian spirit, quiet, grounded, and oddly comforting on a tea table. Its dark, matte surface and carved details feel like something found in a forgotten shrine or tucked into a wooden box of charms. Place it beside your teapot, and it becomes part of the ritual: a steady presence while the kettle sings and the world slows down.",series:"Tea Spirits",vibe:"",atmosphere:"",personality:"",profile:[]},
    {name:"Six-Eyed Spirit Bird",mood:"Snarky six-eyed magpie.",avail:0,url:"https://darksagaart.etsy.com/listing/4428438139/",img:"/assets/works/tea/six-eyed-spirit-bird/01.webp",photos:["/assets/works/tea/six-eyed-spirit-bird/01.webp", "/assets/works/tea/six-eyed-spirit-bird/02.webp", "/assets/works/tea/six-eyed-spirit-bird/03.webp", "/assets/works/tea/six-eyed-spirit-bird/04.webp"],story:"This design is inspired by modern Korean animation folklore. Bring the mischievous charm of Korean myths and art to your tea table with this handmade Magpie tea pet. Known as the snarky, six-eyed familiar, she is the perfect companion for those who like their tea with a side of mystery and a hint of demon-hunting magic. This magpie represents playful cunning and loyalty. In your tea ceremony, she acts as a Watcher of the Brew, ensuring every steep is perfect.",series:"Tea Spirits",vibe:"",atmosphere:"Mystical · Snarky · Modern Folklore",personality:"Mischievous · Alert · Cultured",profile:[]},
    {name:"Master of the Forest",mood:"Calm horned spirit.",avail:0,url:"https://darksagaart.etsy.com/listing/4428426389/",img:"/assets/works/tea/master-of-the-forest/01.webp",photos:["/assets/works/tea/master-of-the-forest/01.webp", "/assets/works/tea/master-of-the-forest/02.webp", "/assets/works/tea/master-of-the-forest/03.webp", "/assets/works/tea/master-of-the-forest/04.webp", "/assets/works/tea/master-of-the-forest/05.webp"],story:"He arrived the way quiet things do, without an entrance, without a warning. Master of the Forest is a handmade unglazed ceramic tea pet shaped like a calm horned spirit, wearing a pale skull mask like a winter moon over dark earth. He rests low and still, as if he's been here longer than the table itself, listening to the kettle and the weather. This one isn't playful, and he isn't in a hurry. He has the kind of presence that makes a room feel calmer, a patient, watchful guardian who prefers silence to noise and meaning to small talk. Set him on your tray and he becomes part of the ritual: a steady shadow at the edge of lamplight, a companion for late sessions, rainy mornings, and conversations that don't need to be rushed. Feed him a little tea, let the warmth pass over him, and watch his surface slowly change, subtle, patient, earned.",series:"Tea Spirits",vibe:"",atmosphere:"",personality:"",profile:[]},
    {name:"Koda",mood:"The root-dreamer.",avail:0,url:"https://darksagaart.etsy.com/listing/4428432021/",img:"/assets/works/tea/koda/01.webp",photos:["/assets/works/tea/koda/01.webp", "/assets/works/tea/koda/02.webp", "/assets/works/tea/koda/03.webp"],story:"Koda The Root-Dreamer is a spirit of the deep woods who has sat in silence for centuries. He is so still and peaceful that tiny forest mushrooms have chosen him as their home. He doesn't hurry; he reminds us that growth takes time and that there is beauty in stillness.",series:"Tea Spirits",vibe:"",atmosphere:"Enchanted Forest · Earthy · Ancient",personality:"Patient · Nurturing · Wise",profile:[]},
    {name:"Noru",mood:"The skyborne dreamer.",avail:0,url:"",img:"/assets/works/tea/noru/01.webp",photos:["/assets/works/tea/noru/01.webp", "/assets/works/tea/noru/02.webp", "/assets/works/tea/noru/03.webp"],story:"Noru is a flying whale spirit who carries little mountains across skies. He is drawn to distant horizons, half-planned journeys, secret maps, and the feeling that somewhere out there another beautiful place is waiting to be found. He drifts to know what is waiting ahead, carrying landscapes, wishes, and unfinished dreams as if they were precious cargo. Keep him near during tea as a small companion for planning future travels, remembering places you miss, or letting your mind wander beyond the room for a while.",series:"Tea Spirits",vibe:"",atmosphere:"Dreamy · Airborne · Wanderlust",personality:"Imaginative · Gentle · Curious · Far-seeing",profile:[]},
    {name:"Vesper",mood:"Small raven of the night sky.",avail:0,url:"https://darksagaart.etsy.com/listing/4496770678/",img:"/assets/works/tea/vesper/01.webp",photos:["/assets/works/tea/vesper/01.webp", "/assets/works/tea/vesper/02.webp", "/assets/works/tea/vesper/03.webp", "/assets/works/tea/vesper/04.webp", "/assets/works/tea/vesper/05.webp"],story:"Vesper, the Night Compass. Vesper is a night raven spirit who appears when the world goes to sleep and the light begins to fade. He is observant, steady, and thoughtful, a companion for evening tea, focused moments, and times when you need to find your own direction. Keep him near your tea tray as a small reminder to slow down, look closer, and trust the small signs.",series:"Tea Spirits",vibe:"",atmosphere:"Nocturnal · Contemplative · Celestial",personality:"Observant · Steady · Wise · Focused",profile:[]},
    {name:"Bracken",mood:"Woodland mushroom spirit.",avail:0,url:"https://darksagaart.etsy.com/listing/4496717840/",img:"/assets/works/tea/bracken/01.webp",photos:["/assets/works/tea/bracken/01.webp", "/assets/works/tea/bracken/02.webp", "/assets/works/tea/bracken/03.webp", "/assets/works/tea/bracken/04.webp", "/assets/works/tea/bracken/05.webp", "/assets/works/tea/bracken/06.webp"],story:"Bracken, the Keeper of Small Secrets. Bracken is a woodland spirit who listens more than he speaks. He knows where the old roots hide their stories, where mushrooms appear after rain, and which fern leaves are best for tucking away tiny secrets. Share your tea with him, and he will keep watch over the thoughts, wishes, and little mysteries of your tea table. You can share your own little secrets with Bracken during tea, or let him inspire fantastic and magical stories while he keeps watch over your tea table.",series:"Tea Spirits",vibe:"",atmosphere:"Earthy · Mysterious · Woodland",personality:"Imaginative · Curious · Protective",profile:[]},
    {name:"Hob",mood:"A little house spirit.",avail:0,url:"https://darksagaart.etsy.com/listing/4496890062/",img:"/assets/works/tea/hob/01.webp",photos:["/assets/works/tea/hob/01.webp", "/assets/works/tea/hob/02.webp", "/assets/works/tea/hob/03.webp", "/assets/works/tea/hob/04.webp", "/assets/works/tea/hob/05.webp", "/assets/works/tea/hob/06.webp"],story:"Hob, the Tea-Table Master Hob is a good-natured little household spirit who believes that every cup, spoon, leaf, and pause should have its proper place. He is the kind of companion who seems to know when the tea needs more time, when the table needs clearing, and when it is better to stop fussing and simply sit for a moment. He is practical, kind, and opinionated. Not in a dramatic way actually, but in the way of someone who has seen many small domestic disasters and knows exactly how they could have been avoided. Keep him near during tea as a tiny adviser for ordinary rituals, important decisions, and companionable silence. Hob feels like a small house spirit who wandered onto the tea tray and immediately decided he could turn the whole arrangement into a cozy magic ritual.",series:"Tea Spirits",vibe:"",atmosphere:"Domestic · Kind · Grounded",personality:"Practical · Good-Natured · Helpful · Gently Opinionated",profile:[]}
  ];

DSA.bastards =
[
    {name:"Queen of Ashes",mood:"Fierce femininity, ruthless strength.",avail:0,url:"https://darksagaart.etsy.com/listing/4461757302/",img:"/assets/works/bastards/queen-of-ashes/01.webp",photos:["/assets/works/bastards/queen-of-ashes/01.webp", "/assets/works/bastards/queen-of-ashes/02.webp", "/assets/works/bastards/queen-of-ashes/03.webp", "/assets/works/bastards/queen-of-ashes/04.webp", "/assets/works/bastards/queen-of-ashes/05.webp", "/assets/works/bastards/queen-of-ashes/06.webp"],story:"She was created for light, beauty, and creation. Elegant and fragile, she loved her world and ruled it with tenderness.\n\nBut when darkness fell upon her kingdom, she did not run. Like a beautiful rose, she grew thorns of cold, forged silver. She traded her delicate rings for heavy armor and took up a two-handed sword.\n\nShe lost everything. But she will never give up, continuing to fight for her beliefs.\n\nShe is the perfect balance of fierce femininity and ruthless strength. Her dusty pink dress and fine lace are a memory of the tenderness she still holds inside. The heavy armor and sword are a promise that she will never step back.\n\nShe did not seek the war, but she will fight for all she loves. Cold. Resolute. Lethally beautiful.",series:"Bastards of the Fall",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Origin", "v": "The Withered Court of the Silver Rose."}, {"k": "Likes", "v": "The scent of roses, the silence of the morning mist, and the cold weight of her sword."}, {"k": "Dislikes", "v": "Cowardice, broken promises, and being underestimated because of her lace."}, {"k": "Dreams", "v": "To see her ruined, forgotten kingdom bloom again."}, {"k": "Fears", "v": "Forgetting the warmth of the world before she had to turn to cold steel."}]},
    {name:"Iron Harlequin",mood:"Echo of the Throne.",avail:1,url:"https://darksagaart.etsy.com/listing/4475210808/",img:"/assets/works/bastards/iron-harlequin/01.webp",photos:["/assets/works/bastards/iron-harlequin/01.webp", "/assets/works/bastards/iron-harlequin/02.webp", "/assets/works/bastards/iron-harlequin/03.webp", "/assets/works/bastards/iron-harlequin/04.webp", "/assets/works/bastards/iron-harlequin/05.webp", "/assets/works/bastards/iron-harlequin/06.webp"],story:"Echo of the Throne. The court always considered him a funny little freak. Aristocrats laughed at his bows, not realizing the motley cap was the perfect vantage point. He possessed a cold, piercing mind, reading others' ambitions, fears, and conspiracies like an open book.\n\nTo everyone he was a silent laughingstock, but to the Queen he was the only advisor whose words were not poisoned by flattery. Only he had the privilege of showing her the cruelest, most unvarnished truth. The blades hidden under heavy velvet were only a final argument; his primary weapon had always been his intellect.\n\nWhen the kingdom turned to ash and the flatterers scattered, the masks fell away. The Queen stepped into the cinders to win back what remained of her world. And he, as before, silently slipped into her shadow.\n\nHe follows her through the ruined lands, completely calm, calculating, and invariably seeing through people. His loyalty is absolute and requires no words. And if anyone tries to betray his Queen, the final argument will be only the quiet, dull ring of metal before a perfectly precise strike.",series:"Bastards of the Fall",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Origin", "v": "The Court of the Fallen Kingdom."}, {"k": "Likes", "v": "Silence, the absolute truth, the weight of his chains, cold steel."}, {"k": "Dislikes", "v": "Empty flattery, noisy crowds, betrayal, and bright, mindless lights."}, {"k": "Dreams", "v": "To see the Queen's domain restored from the ash, and to see the end of all lies."}, {"k": "Special feature", "v": "Exceptional four-armed dexterity and a gaze that reads human souls like an open book."}, {"k": "Fears", "v": "Failing his Queen, and becoming the mindless puppet the court once believed him to be."}]},
    {name:"Gentleman of the Lower City",mood:"A charming thief of the gas-lit city.",avail:1,url:"https://darksagaart.etsy.com/listing/4467203036/",img:"/assets/works/bastards/gentleman-of-the-lower-city/01.webp",photos:["/assets/works/bastards/gentleman-of-the-lower-city/01.webp", "/assets/works/bastards/gentleman-of-the-lower-city/02.webp", "/assets/works/bastards/gentleman-of-the-lower-city/03.webp", "/assets/works/bastards/gentleman-of-the-lower-city/04.webp", "/assets/works/bastards/gentleman-of-the-lower-city/05.webp", "/assets/works/bastards/gentleman-of-the-lower-city/06.webp", "/assets/works/bastards/gentleman-of-the-lower-city/07.webp"],story:"The yellow glow of gas lamps struggles through the thick factory smog. A police whistle shrieks below, but on the wrought-iron cornice absolute calm prevails. An elegant figure in a dapper vest casually tosses a heavy coin purse. A flash of lightning reflects in his brass goggles, revealing a mocking smirk before he melts into the labyrinth of steam boilers.\n\nIn the Upper City archives his file is just wild guesses and complaints from influential aristocrats. He bears no grand titles, yet pompous lords instinctively clutch their wallets when they spot the familiar gleam of his goggles and worn leather baldric.\n\nThis fellow is a virtuoso of dark alleys and a genius of bluffing. He considers his brass prosthetic hook, a souvenir from a close call with a patrol cruiser's gears, an amusing occupational hazard. It is perfectly suited for picking complex locks, scaling drainpipes, and serving as a persuasive argument in card games.\n\nHis impeccable manners open the heaviest oak doors of high society. He robs the overly arrogant, swindles the overly confident, and escapes across rain-slicked roofs, cheerfully saluting his pursuers with his rapier. For him, every heist is high art. He leaves behind only a faint scent of machine oil, a night breeze, and absolute emptiness in their safes.\n\nAnd while panic rises below, he is already perched on a clock tower spire, casually tossing a stolen gold chronometer in his good hand, looking out for his next daring target.",series:"Bastards of the Fall",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Vibe", "v": "High-society swindler and master of the bluff."}, {"k": "Likes", "v": "Extreme risks, dangerous challenges, and unpredictable adventures."}, {"k": "Dislikes", "v": "The boring, predictable life of ordinary citizens."}, {"k": "Special trick", "v": "Can pick a safe with his brass hook while giving a polite compliment."}, {"k": "Quirks", "v": "Never takes off his goggles."}]},
    {name:"The Librarian",mood:"Keeper of forgotten languages.",avail:0,url:"https://darksagaart.etsy.com/listing/4341646227/",img:"/assets/works/bastards/the-librarian/01.webp",photos:["/assets/works/bastards/the-librarian/01.webp", "/assets/works/bastards/the-librarian/02.webp", "/assets/works/bastards/the-librarian/03.webp", "/assets/works/bastards/the-librarian/04.webp", "/assets/works/bastards/the-librarian/05.webp", "/assets/works/bastards/the-librarian/06.webp"],story:"The Librarian does not walk the streets of ordinary cities. This mystical creature belongs to the shifting corridors of the dreamscape, where fading thoughts turn into dust and lost knowledge thickens into mist. As worlds vanish and civilisations crumble, this silent keeper travels between realities, gathering the fragments of ancient stories and preserving the final whispers of forgotten knowledge before they disappear forever into absolute nothingness.\n\nThe Librarian is a living reminder that the most profound secrets, the ones that can truly change a soul, are never shouted. They are always hidden in the dark, waiting between the lines of an unread book.",series:"Bastards of the Fall",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Name", "v": "Unknown. The Librarian believes everyone should keep their own secrets."}, {"k": "Origin", "v": "Born within the surreal landscape of forgotten dreams."}, {"k": "Likes", "v": "Midnight silence, the wind, lavender tea, abandoned manuscripts, and the flicker of a campfire."}, {"k": "Dislikes", "v": "Empty chatter, loud unwanted advice, and those who mistreat books."}, {"k": "Special talents", "v": "Mastering long silences, looking straight into human souls, and vanishing into thin air when least expected."}, {"k": "Secret gift", "v": "The unique ability to transform what is forgotten into what is deeply needed."}, {"k": "Vibe", "v": "Calm, observant, and reserved. A presence that feels incredibly cozy, yet beautifully strange."}]}
  ];

DSA.urban =
[
    {name:"Dandy of Decay",mood:"A melancholic poet of the night city.",avail:1,url:"https://darksagaart.etsy.com/listing/4532535636",img:"/assets/works/urban/dandy-of-decay/01.webp",photos:["/assets/works/urban/dandy-of-decay/01.webp","/assets/works/urban/dandy-of-decay/02.webp","/assets/works/urban/dandy-of-decay/03.webp","/assets/works/urban/dandy-of-decay/04.webp","/assets/works/urban/dandy-of-decay/05.webp","/assets/works/urban/dandy-of-decay/06.webp","/assets/works/urban/dandy-of-decay/07.webp","/assets/works/urban/dandy-of-decay/08.webp","/assets/works/urban/dandy-of-decay/09.webp"],story:"He moves through the city with the quiet demeanor of a ghost, preferring the secluded halls of old libraries or the occasional abandoned mansion where time is frozen in layers of dust over busy evening boulevards. For him, such places are the genuine bones of the city, stripped of the fake glare of storefronts. They are clusters of untold stories and pure sources of inspiration. In his pockets, there is always room for a notebook and a heavy fountain pen.\n\nHis poems read like the diary of a melancholic, where gothic longing intertwines with the silence of the night city. In Edgar Allan Poe's work he values more than dark plots. He respects the logic and the honest look at fear that help him stay true to himself against outside influence. He is introverted and a man of few words, yet he is always ready to bring a conversationalist back to reality with a sharp, cold quote the moment their pretense begins to weary him.",series:"Urban Misfits",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Beliefs", "v": "Our world is an endless rough draft, where everyone has the right to make mistakes and change. Trying to appear perfect and flawless only kills the real life within people."}, {"k": "Fashion", "v": "A strict gothic aesthetic that does not follow modern trends, worn to emphasize his independence from other people's tastes."}, {"k": "Favorite Authors", "v": ["Edgar Allan Poe", "Charles Baudelaire", "Joris-Karl Huysmans"]}, {"k": "Likes", "v": ["Avant-garde theater", "Poetry readings", "Thunderstorms", "Walking at night in the rain", "The tactile feel of physical books"]}, {"k": "Dislikes", "v": ["Forced optimism", "Modern gadgets and their filters", "Tastelessness", "Vulgarity", "Kitsch"]}, {"k": "Writing Ritual", "v": "A meditative process of crafting lines with a fountain pen on paper."}, {"k": "Communication Style", "v": "Speaks little and cuts straight to the point with an ironic quote."}]},
    {name:"Master of the Forest",mood:"Old god of the city's edges.",avail:1,url:"https://darksagaart.etsy.com/listing/4493639842/",img:"/assets/works/urban/master-of-the-forest/01.webp",photos:["/assets/works/urban/master-of-the-forest/01.webp", "/assets/works/urban/master-of-the-forest/02.webp", "/assets/works/urban/master-of-the-forest/03.webp", "/assets/works/urban/master-of-the-forest/04.webp", "/assets/works/urban/master-of-the-forest/05.webp", "/assets/works/urban/master-of-the-forest/06.webp", "/assets/works/urban/master-of-the-forest/07.webp"],story:"He used to belong to the deep woods. These days his territory is broader and far less romantic: vacant lots behind supermarkets, overgrown railway embankments, courtyards between apartment blocks, abandoned construction sites, and cracks in the asphalt where green things still insist on coming back.\n\nHe watches the concrete jungle take more and more ground with a philosophical kind of amusement. The city may act like it has already won, but he is patient enough to know better. In the long run, he is certain, Nature will reclaim what is hers.\n\nHe has his own way of dealing with people, too. For the arrogant ones, the route home may suddenly become oddly unhelpful: a wrong turn here, a familiar yard that somehow feels unfamiliar there. But for someone truly looking for a way out, the right path has a habit of appearing sooner than expected.\n\nHe remembers the old world perfectly well, but he learned to live in the new one. He is curious about modern life, studies its strange inventions and habits, drinks herbal blends, appreciates a good espresso, and keeps a close eye on every small living creature that still survives among concrete and noise.\n\nIf people believe a species has disappeared, that does not necessarily mean it is gone. There is every chance the Master of the Forest has already hidden the last survivors somewhere safe, far from people and their endless plans.",series:"Urban Misfits",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Who is he", "v": "An old keeper of wild places who adapted to the modern city without becoming part of it."}, {"k": "Usually found", "v": "Vacant lots, overgrown rail lines, courtyards, abandoned sites, and the edges of places people stopped noticing."}, {"k": "Temperament", "v": "Calm, stubborn, curious, and quietly amused."}, {"k": "Likes", "v": "Sunsets, herbal blends, good espresso, rare species, and all kinds of living creatures."}, {"k": "Dislikes", "v": "Waste, cruelty, pointless noise, and people who see life as disposable."}, {"k": "Belief", "v": "Nature always comes back."}, {"k": "Principles", "v": "Vegetarian. Eco-activist. On the side of the living."}, {"k": "Passion", "v": "Creating hidden sanctuaries for endangered species."}, {"k": "Quirks", "v": "He may interrupt any conversation to rescue a beetle, move a snail off the pavement, or inspect a strange seed."}]},
    {name:"The Dreamer",mood:"Lo-fi street artist.",avail:1,url:"https://darksagaart.etsy.com/listing/4344991958/",img:"/assets/works/urban/the-dreamer/01.webp",photos:["/assets/works/urban/the-dreamer/01.webp", "/assets/works/urban/the-dreamer/02.webp", "/assets/works/urban/the-dreamer/03.webp", "/assets/works/urban/the-dreamer/04.webp", "/assets/works/urban/the-dreamer/05.webp", "/assets/works/urban/the-dreamer/06.webp"],story:"He steps out when the city finally goes to sleep and the neon lights blur in the rain puddles. To the rest of the world he is just a silent shadow in a hoodie, headphones glued to his ears. But where others see only cold, blank concrete walls, he sees a canvas.\n\nHis art is a quiet conversation with the city. The hiss of his spray can is a secret language, telling stories on brick walls while lo-fi beats mix with water dripping from the roofs. By sunrise he is already high up on a rooftop, leaving his painted birds behind to remind the rushing morning crowds to stop and breathe.",series:"Urban Misfits",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Likes", "v": ["Long, quiet walks through empty streets", "Painting graffiti when the city is asleep", "Lo-fi music mixed with the sound of rain", "Summer sunsets on rooftops"]}, {"k": "Dislikes", "v": ["Loud crowds and meaningless chatter", "Flashy luxury aesthetics", "Cheap bread (don't ask)"]}, {"k": "Unique traits", "v": ["Always carries his spray cans", "Often draws birds, says they reflect him best", "Feels most alive in the moments most people miss"]}]},
    {name:"The Observer",mood:"The quiet elf.",avail:0,url:"https://darksagaart.etsy.com/listing/4419480534/",img:"/assets/works/urban/the-observer/01.webp",photos:["/assets/works/urban/the-observer/01.webp", "/assets/works/urban/the-observer/02.webp", "/assets/works/urban/the-observer/03.webp", "/assets/works/urban/the-observer/04.webp", "/assets/works/urban/the-observer/05.webp", "/assets/works/urban/the-observer/06.webp"],story:"While the modern city screams in a blur of neon and traffic, he sits right in the middle of it, completely untouched by the noise. With his favorite plant pot safely by his side and a cup of steaming tea in his hands, this modern elf tunes into a different frequency.\n\nBehind his calm, thoughtful eyes is a mind that reads the city's hidden rhythms. To him, the steady, hypnotic beats of psy-trance are the perfect background music for watching the clouds shift and the daylight change. He communicates through the precise, elegant strokes of his calligraphy brushes and the little conversations he shares with his plants.",series:"Urban Misfits",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Personality", "v": ["Calm and thoughtful", "Quiet, likes to observe", "Very neat and careful"]}, {"k": "Likes", "v": ["Drinking tea", "Calligraphy and sumi-e", "Psy trance and deep, steady beats", "Plants and green corners at home", "Watching the sky, trees and changing light"]}, {"k": "Little quirk", "v": ["Talks to his plants", "Feels safe when his favorite plant pot is close"]}]},
    {name:"The Garden Snail",mood:"Slow and cheerful wanderer.",avail:0,url:"https://darksagaart.etsy.com/listing/4423741901/",img:"/assets/works/urban/the-garden-snail/01.webp",photos:["/assets/works/urban/the-garden-snail/01.webp", "/assets/works/urban/the-garden-snail/02.webp", "/assets/works/urban/the-garden-snail/03.webp", "/assets/works/urban/the-garden-snail/04.webp", "/assets/works/urban/the-garden-snail/05.webp", "/assets/works/urban/the-garden-snail/06.webp"],story:"This cheerful little spirit lives where the morning dew meets the scent of wild strawberries. While the rest of the world rushes by in a blur of fast decisions, this gentle creature prefers a different pace: one measured in summer rain showers and the slow opening of flower petals.\n\nEquipped with a tiny, naive heart and an unshakeable belief in magic, this soul keeps a watchful eye over the garden, whispering to growing seedlings and tracking the sun across the leaves. To this whimsical companion, every blooming bud is a miracle, and every quiet corner of the forest is a safe haven.",series:"Urban Misfits",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Likes", "v": ["Warm rain in summer", "Growing plants and flowers", "Slow walks in the garden"]}, {"k": "Dislikes", "v": ["Fast decisions", "Chaos", "Rude and unfriendly guys"]}]}
  ];

DSA.spores =
[
    {name:"MarshmallOwl",mood:"A sunny-hearted owl of cocoa and books.",avail:0,url:"https://darksagaart.etsy.com/listing/4537250897",img:"/assets/works/spores/marshmallowl/01.webp",photos:["/assets/works/spores/marshmallowl/01.webp", "/assets/works/spores/marshmallowl/02.webp", "/assets/works/spores/marshmallowl/03.webp", "/assets/works/spores/marshmallowl/04.webp", "/assets/works/spores/marshmallowl/05.webp", "/assets/works/spores/marshmallowl/06.webp", "/assets/works/spores/marshmallowl/07.webp", "/assets/works/spores/marshmallowl/08.webp", "/assets/works/spores/marshmallowl/09.webp"],story:"She embodies a joyful, sunny day on the veranda. Her presence fills the space with genuine cheer and a sense of absolute coziness. The aroma of hot chocolate, sweet marshmallows, and freshly printed pages always lingers in the air.\n\nShe possesses an extraordinary gift of empathy, intuitively sensing the mood of others and generously sharing her positivity.\n\nEvery adorable trinket nearby takes on a special meaning, adding a spark of joy to everyday life.\n\nShe is a concentrate of pure friendliness, warming hearts and inspiring the brightest emotions, accompanied by sincere, ringing laughter.",series:"Spores",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Vibe", "v": "Sunny veranda, ringing laughter, aroma of cocoa with marshmallows, absolute comfort."}, {"k": "Character", "v": ["Empathetic", "Cheerful", "Open-hearted", "Friendly"]}, {"k": "Loves", "v": ["Life", "Sunlight", "Laughter", "Cocoa with a mountain of marshmallows", "Reading", "Good company", "Cute trinkets", "Jokes"]}, {"k": "Avoids", "v": ["Rainy weather", "Gloomy days", "Melancholy", "Boredom"]}]},
    {name:"Skyline Nomad",mood:"Rooftop spirit chasing wind.",avail:0,url:"https://darksagaart.etsy.com/listing/4508369970/",img:"/assets/works/spores/skyline-nomad/01.webp",photos:["/assets/works/spores/skyline-nomad/01.webp", "/assets/works/spores/skyline-nomad/02.webp", "/assets/works/spores/skyline-nomad/03.webp", "/assets/works/spores/skyline-nomad/04.webp", "/assets/works/spores/skyline-nomad/05.webp", "/assets/works/spores/skyline-nomad/06.webp"],story:"He dwells where the city's concrete constraints end and the open expanse begins. The Skyline Nomad is a spirit of the heights, driven by a physical need for the wind in his face and constant motion. He shares the upper realm with the birds and balances on the edges of the abyss for the pure, intoxicating feeling of freedom.\n\nIf you have ever felt the urge to escape the suffocating noise of the streets and find peace on a high, wind-swept roof, this little nomad is your perfect companion. He is a listener for those who find comfort and freedom in the heights.",series:"Spores",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Likes", "v": "The smell of ozone right before a thunderstorm, the vibration of subway trains echoing up through the walls, the rumble of old ventilation units."}, {"k": "Dislikes", "v": "Sitting still for too long."}, {"k": "Biggest fear", "v": "Being permanently grounded, or trapped in a windowless basement."}, {"k": "Habits", "v": "Dropping tiny pebbles down deep ventilation shafts to listen to the echo bounce."}, {"k": "Secrets", "v": "Hides a collection of small human things snatched under loose roof tiles."}]},
    {name:"The Roastery Kodama",mood:"Fueled by specialty coffee.",avail:0,url:"https://darksagaart.etsy.com/listing/4505211581/",img:"/assets/works/spores/the-roastery-kodama/01.webp",photos:["/assets/works/spores/the-roastery-kodama/01.webp", "/assets/works/spores/the-roastery-kodama/02.webp", "/assets/works/spores/the-roastery-kodama/03.webp", "/assets/works/spores/the-roastery-kodama/04.webp", "/assets/works/spores/the-roastery-kodama/05.webp", "/assets/works/spores/the-roastery-kodama/06.webp"],story:"He is concentrated life energy, the invisible force that shakes the city out of its slumber.\n\nOnce, this forest spirit matured in the warm gloom of tropical lands, for years soaking up the juices from the roots of wild coffee groves. Since moving to the megalopolis, he has quickly found his new power spots: the fragrant, sun-warmed corners of roasting houses and specialty coffee shops.\n\nHe has become the Roastery Kodama, a spirit-resonator who sincerely adores the morning rush, the hum of industrial roasters, and the thick, intoxicating scent of a fresh grind.\n\nA companion to early birds and midnight thinkers. He is a reminder: to truly wake up, find your voice, and embrace a new day, you must simply shed your old, outgrown shell.",series:"Spores",vibe:"",atmosphere:"",personality:"",profile:[{"k": "Vibe", "v": "The hyperactive soulmate who never sleeps and charges everyone around him with electric energy."}, {"k": "Hangouts", "v": "Top shelves of indie bookstores, tucked inside burlap coffee sacks, or perched behind industrial roasting exhausts where the air is warmest."}, {"k": "Likes", "v": ["Singing at the top of his lungs in sync with professional coffee grinders (he thinks they are performing a duet).", "The scent of 100% Arabica with anaerobic fermentation.", "Snuggling inside coffee bean bags.", "Overhearing deep, late-night conversations."]}, {"k": "Dislikes", "v": ["Instant 3-in-1 coffee (he considers it a personal insult and a crime against nature)."]}, {"k": "Secret tricks", "v": ["Left on your shelf next to a real coffee bean, he guards you against morning grogginess.", "At night he secretly tweaks the grind settings on espresso machines with his gear-wheel to make the flavour woodsier. Baristas are baffled the next morning."]}]}
  ];

/* DROP — работы текущего дропа (единый источник для превью на главной и страницы /drop/).
   Дроп от 2026-08-20: Cats Between Cups (Tea Spirits, 3 ти-пета: Murr, Stacklings, Purr).
   Продаётся на Etsy. НЕ дублируем объекты: берём их из DSA.tea по группе coll
   (одна правка — везде синхронно). После дропа сбросить обратно к `DSA.drop = [];`
   (см. правило сброса). */
DSA.drop = DSA.tea.filter(function(o){ return o.coll === "Cats Between Cups"; });

/* DROP / NEWS — конфиг анонса дропа (status:off по умолчанию) */
DSA.DROP =
{
    status:'live',                                  // 'off' | 'soon' | 'live' — переключаешь руками
    date:'2026-08-20',                              // день дропа (для отсчёта в 'soon')
    liveSince:'2026-08-20',                         // дата запуска 'live'; через liveDays сайт сам уходит в 'off'
    liveDays:14,                                    // сколько дней висит дроп, потом авто-возврат
    type:'teapets',                                 // 'teapets' | 'dolls' — Cats Between Cups это серия ти-петов
    comingImg:'/assets/drop/coming.webp',            // фон-тизер в «скоро» (под вуалью, в hero-карусели главной) — дефолт
    cover:'/assets/drop/cover.webp',                 // фон hero страницы /drop/ — дефолтная заглушка (кастомную картину под этот дроп ещё рисуем)
    accent:'glow',                                  // акцент карусели в live: 'calm'|'shimmer'|'sparkle'|'glow' — светящиеся глаза котов → glow
    featured:{img:'/assets/drop/cats-featured.webp', name:'Cats Between Cups'}, // обложка дропа в hero-карусели во время live (групповое фото трёх котов)
    // Магазин дропа (историческое имя поля `etsy` = «ссылка на магазин дропа»). Этот дроп — на Etsy.
    // Текст кнопок/ленты берётся из ХОСТА ссылки, см. shopMeta() в app.js.
    etsy:'https://darksagaart.etsy.com',
    // Кастомные тексты hero страницы /drop/ в 'live' (перекрывают дефолт). Очисти/убери для след. дропа.
    titleLive:'Cats Between Cups',
    leadLive:'Three cats just claimed their spots between the cups. Each one is one-of-a-kind — adopt yours before someone else takes the seat.'
    // ribbonSoon (кастомные строки бегущей ленты в 'soon') не заданы — для live не нужны,
    // используется дефолтный текст. Добавь массив ribbonSoon:[...] при следующем 'soon'-анонсе.
  };

/* DEV: на localhost статус дропа переопределяется через ?drop=off|soon|live и
   ЗАПОМИНАЕТСЯ в sessionStorage — чтобы при переходах между страницами выбранный
   статус сохранялся (иначе ссылки без ?drop= открывали бы страницу в 'off').
   На боевом не срабатывает; реальный статус всегда берётся из DSA.DROP.status. */
(function(){
  var local=['localhost','127.0.0.1','::1','0.0.0.0'].indexOf(location.hostname)>=0;
  if(!local) return;
  var ok={off:1,soon:1,live:1};
  var q=new URLSearchParams(location.search).get('drop');
  if(q&&ok[q]){ try{sessionStorage.setItem('dsa-droptest',q);}catch(e){} }
  var s=(q&&ok[q])?q:null;
  if(!s){ try{var v=sessionStorage.getItem('dsa-droptest'); if(v&&ok[v]) s=v;}catch(e){} }
  if(s) DSA.DROP.status=s;
})();
